    /// Slice `generated` from `start` up to `end` (or the end of the string).
    fn section_between<'a>(generated: &'a str, start: &str, end: &str) -> &'a str {
        let from = generated
            .find(start)
            .unwrap_or_else(|| panic!("missing `{start}` in generated code"));
        let rest = &generated[from..];
        let to = rest.find(end).unwrap_or(rest.len());
        &rest[..to]
    }

    #[test]
    fn repository_macro_save_validates_after_normalize_before_insert() {
        // #2586: `save` runs the model's `#[validate]` rules on every caller —
        // a job, a seed, a resolver — not only the generated REST handlers.
        // Order: normalize, then validate, then insert.
        let generated =
            repository_macro(quote! { Post }, quote! { pub trait PostRepository {} }).to_string();
        let section = section_between(&generated, "async fn save (", "async fn update (");

        let normalize_at = section
            .find("spez_normalize ()")
            .expect("save must normalize the payload");
        // Pinned to the single-ref form: `MaybeValidate (& new)` would wrap a
        // `&&New*`, which takes the autoref no-op arm and validates nothing.
        let validate_at = section
            .find("MaybeValidate (new)")
            .expect("save must validate the payload");
        let insert_at = section.find("insert_into").expect("save must insert");
        assert!(
            normalize_at < validate_at && validate_at < insert_at,
            "save must normalize, then validate, then insert: {section}"
        );
    }

    #[test]
    fn repository_macro_save_validates_on_every_config_branch() {
        // #2586 names four `save` bodies — blind, hooked, tenant-scoped and
        // versioned. The splice sits at the one point they are composed, so
        // prove that rather than trusting it.
        for attr in [
            quote! { Post },
            quote! { Post, hooks = PostHooks },
            quote! { Post, tenant_scoped },
            quote! { Post, versioned = true },
            quote! { Post, tenant_scoped, sharded },
        ] {
            let label = attr.to_string();
            let generated =
                repository_macro(attr, quote! { pub trait PostRepository {} }).to_string();
            let section = section_between(&generated, "async fn save (", "async fn update (");
            assert!(
                section.contains("MaybeValidate (new)"),
                "`{label}` must validate on the insert path: {section}"
            );
        }
    }

    #[test]
    fn repository_macro_hooked_save_validates_before_before_create() {
        // #2586: on a hooked repository the rules run before `before_create`,
        // as `docs/guide/forms.md` states.
        let generated = repository_macro(
            quote! { Post, hooks = PostHooks },
            quote! { pub trait PostRepository {} },
        )
        .to_string();
        let section = section_between(&generated, "async fn save (", "async fn update (");

        let validate_at = section
            .find("MaybeValidate (new)")
            .expect("hooked save must validate the payload");
        let hook_at = section
            .find("before_create")
            .expect("hooked save must run before_create");
        assert!(
            validate_at < hook_at,
            "validation must run before the before_create hook: {section}"
        );
    }

    #[test]
    fn repository_macro_save_many_validates_each_row_before_insert() {
        // #2586: the bulk insert path validates every row before writing any.
        let generated =
            repository_macro(quote! { Post }, quote! { pub trait PostRepository {} }).to_string();
        let section = section_between(
            &generated,
            "async fn save_many (",
            "async fn save_many_skip_invalid (",
        );

        let validate_at = section
            .find("MaybeValidate (__autumn_row)")
            .expect("save_many must validate each row");
        let insert_at = section.find("insert_into").expect("save_many must insert");
        assert!(
            validate_at < insert_at,
            "every row must be validated before the batch insert: {section}"
        );
    }

    #[test]
    fn repository_macro_save_many_skip_invalid_normalizes_and_reports_rows() {
        // #2586: skip-invalid keeps its partial-success contract — a row the
        // model rejects is reported by index, not raised. It also normalizes
        // first, so validators see the same canonical value `save` gives them.
        let generated =
            repository_macro(quote! { Post }, quote! { pub trait PostRepository {} }).to_string();
        let section = section_between(
            &generated,
            "async fn save_many_skip_invalid (",
            "async fn update_many (",
        );

        let normalize_at = section
            .find("spez_normalize_many ()")
            .expect("skip-invalid must normalize rows");
        let validate_at = section
            .find("MaybeValidate")
            .expect("skip-invalid must validate rows");
        assert!(
            normalize_at < validate_at,
            "rows must be normalized before validation: {section}"
        );
        assert!(
            section.contains("failures . push"),
            "an invalid row must be reported, not raised: {section}"
        );
    }

    #[test]
    fn repository_macro_hooked_save_many_skip_invalid_validates_before_hook() {
        // #2586: same contract on the hooked skip-invalid path.
        let generated = repository_macro(
            quote! { Post, hooks = PostHooks },
            quote! { pub trait PostRepository {} },
        )
        .to_string();
        let section = section_between(
            &generated,
            "async fn save_many_skip_invalid (",
            "async fn update_many (",
        );

        let validate_at = section
            .find("MaybeValidate")
            .expect("hooked skip-invalid must validate rows");
        let hook_at = section
            .find("before_create")
            .expect("hooked skip-invalid must run before_create");
        assert!(
            validate_at < hook_at,
            "validation must run before before_create: {section}"
        );
    }

    #[test]
    fn repository_macro_find_or_create_by_validates_before_insert() {
        // #2586: the get-or-insert path validates only when it is about to
        // insert, so an existing row is still returned for a payload the model
        // would reject.
        let generated = repository_macro(
            quote! { Post },
            quote! {
                pub trait PostRepository {
                    fn find_or_create_by_slug(&self, slug: String, new: &NewPost);
                }
            },
        )
        .to_string();
        let section = section_between(
            &generated,
            "pub async fn find_or_create_by_slug",
            "impl :: autumn_web :: tenancy :: HasTenantIdColumn",
        );

        let lookup_at = section
            .find("__autumn_acquire_read_conn")
            .expect("get-or-insert must look up first");
        let validate_at = section
            .find("MaybeValidate (new)")
            .expect("get-or-insert must validate the payload");
        let insert_at = section
            .find("insert_into")
            .expect("get-or-insert must insert");
        assert!(
            lookup_at < validate_at && validate_at < insert_at,
            "validation must sit between the lookup and the insert: {section}"
        );
    }

    #[test]
    fn repository_macro_blind_update_still_validates_nothing() {
        // #2586 guard rail: the fix is insert-only. A no-hooks, no-knob
        // repository keeps the documented blind update path.
        let generated =
            repository_macro(quote! { Post }, quote! { pub trait PostRepository {} }).to_string();
        let section = section_between(&generated, "async fn update (", "async fn delete_by_id (");

        assert!(
            !section.contains("MaybeValidate"),
            "the blind update path must stay unvalidated: {section}"
        );
    }

    #[test]
    fn repository_macro_api_create_validates_before_save() {
        // #1253: create runs `#[validate]` rules (via autoref `MaybeValidate`)
        // before the insert, returning 422 on failure.
        let generated = repository_macro(
            quote! { Post, api = "/api/posts" },
            quote! { pub trait PostRepository {} },
        )
        .to_string();

        let start = generated
            .find("async fn post_api_create")
            .expect("create handler must be generated");
        let rest = &generated[start..];
        let end = rest
            .find("fn __autumn_route_info_post_api_create")
            .unwrap_or(rest.len());
        let section = &rest[..end];

        let validate_at = section
            .find("MaybeValidate")
            .expect("create handler must validate the payload");
        let save_at = section
            .find("repo . save")
            .expect("create handler must save");
        assert!(
            validate_at < save_at,
            "validation must run before the insert: {section}"
        );
        assert!(
            section.contains("autumn_maybe_validate"),
            "create handler must call autumn_maybe_validate: {section}"
        );
    }

    #[test]
    fn repository_macro_api_update_validates() {
        // #1253: the update path applies the same validate-then-422 wiring.
        let generated = repository_macro(
            quote! { Post, api = "/api/posts" },
            quote! { pub trait PostRepository {} },
        )
        .to_string();

        let start = generated
            .find("async fn post_api_update")
            .expect("update handler must be generated");
        let rest = &generated[start..];
        let end = rest
            .find("fn __autumn_route_info_post_api_update")
            .unwrap_or(rest.len());
        let section = &rest[..end];
        assert!(
            section.contains("MaybeValidate (& patch)"),
            "update handler must validate the patch payload: {section}"
        );
    }

    #[test]
    fn repository_macro_api_policy_update_validates_after_policy_check() {
        // #1719 follow-up: on the policy-backed update handler, payload
        // validation (422) must run *after* the existence load (404) and the
        // `__check_policy_scoped` authorization gate (403), so a policy-gated
        // PUT/PATCH with an invalid body still returns 404/403 before 422.
        // Validation-first here regressed the ordering (Codex P2).
        let generated = repository_macro(
            quote! { Post, api = "/api/posts", policy = PostPolicy },
            quote! { pub trait PostRepository {} },
        )
        .to_string();

        let start = generated
            .find("async fn post_api_update")
            .expect("policy update handler must be generated");
        let rest = &generated[start..];
        let end = rest
            .find("fn __autumn_route_info_post_api_update")
            .unwrap_or(rest.len());
        let section = &rest[..end];

        let policy_at = section
            .find("__check_policy_scoped")
            .expect("policy update handler must run the scoped policy check");
        let validate_at = section
            .find("autumn_maybe_validate")
            .expect("policy update handler must validate the patch payload");
        assert!(
            policy_at < validate_at,
            "policy check (403) and existence load (404) must run before \
             patch validation (422): {section}"
        );
    }

    #[test]
    fn repository_macro_no_hooks_validate_on_update_emits_from_patch() {
        // #1801: with `validate_on_update = fetch` on a plain no-hooks repo, the
        // generated single-record `update` body validates the effective merged
        // model via `from_patch` (existing row ∪ patch), surfacing the standard
        // 422 for a patch that only becomes invalid once merged.
        let generated = repository_macro(
            quote! { Post, validate_on_update = fetch },
            quote! { pub trait PostRepository {} },
        )
        .to_string();
        let section = update_section(&generated);
        assert!(
            section.contains("from_patch"),
            "validate_on_update = fetch must emit a from_patch merged-model check \
             on the no-hooks update path: {section}"
        );
    }

    #[test]
    fn repository_macro_tenant_scoped_validate_on_update_tenant_filters_load() {
        // #1801 follow-up: on a `tenant_scoped` no-hooks repo WITH the knob, the
        // blind (no version-check) sub-branch must load the current row for
        // merged validation through the SAME tenant filter its own blind UPDATE
        // uses — otherwise a cross-tenant `id` would load a foreign row and
        // surface 422 instead of the correct 404. Assert the update body both
        // emits the `from_patch` merged check and tenant-filters the load.
        let generated = repository_macro(
            quote! { Post, tenant_scoped, validate_on_update = fetch },
            quote! { pub trait PostRepository {} },
        )
        .to_string();
        let section = update_section(&generated);
        assert!(
            section.contains("from_patch"),
            "tenant_scoped + validate_on_update = fetch must emit a from_patch \
             merged-model check: {section}"
        );
        assert!(
            section.contains("tenant_id . eq"),
            "the tenant_scoped blind merged-validation load must be tenant-filtered \
             (tenant_id.eq), matching its own blind UPDATE: {section}"
        );
    }

    #[test]
    fn repository_macro_versioned_validate_on_update_emits_from_patch() {
        // #1801 follow-up: a `versioned` no-hooks repo WITH the knob emits the
        // merged-model `from_patch` check on its update body too.
        let generated = repository_macro(
            quote! { Post, versioned = true, validate_on_update = fetch },
            quote! { pub trait PostRepository {} },
        )
        .to_string();
        let section = update_section(&generated);
        assert!(
            section.contains("from_patch"),
            "versioned + validate_on_update = fetch must emit a from_patch \
             merged-model check: {section}"
        );
    }

    #[test]
    fn repository_macro_no_hooks_without_knob_has_no_from_patch() {
        // #1801 AC #2: without the opt-in knob, the blind no-hooks update path
        // stays byte-for-byte as before — no `from_patch` call, so no
        // unconditional extra SELECT or merged validation.
        let generated =
            repository_macro(quote! { Post }, quote! { pub trait PostRepository {} }).to_string();
        let section = update_section(&generated);
        assert!(
            !section.contains("from_patch"),
            "a no-hooks repo without validate_on_update must not emit a from_patch \
             merged-model check on the update path: {section}"
        );
    }

    #[test]
    fn repository_macro_api_policy_update_validates_merged_model() {
        // #1801 sub-case 1: the policy `--api` update handler unconditionally
        // validates the effective merged model via `from_patch` on the already
        // loaded `__existing` row (zero extra query), independent of the knob.
        let generated = repository_macro(
            quote! { Post, api = "/api/posts", policy = PostPolicy },
            quote! { pub trait PostRepository {} },
        )
        .to_string();

        let start = generated
            .find("async fn post_api_update")
            .expect("policy update handler must be generated");
        let rest = &generated[start..];
        let end = rest
            .find("fn __autumn_route_info_post_api_update")
            .unwrap_or(rest.len());
        let section = &rest[..end];

        assert!(
            section.contains("from_patch (& __existing"),
            "policy update handler must validate the merged model via from_patch on \
             the loaded __existing row (zero extra query): {section}"
        );
        let from_patch_at = section
            .find("from_patch")
            .expect("policy update handler must validate the merged model via from_patch");
        // The merged validation must run after the policy gate (403) so ordering
        // stays 404 -> 403 -> patch-422 -> merged-422.
        let policy_at = section
            .find("__check_policy_scoped")
            .expect("policy update handler must run the scoped policy check");
        assert!(
            policy_at < from_patch_at,
            "merged-model validation must run after the policy check: {section}"
        );
    }

